"use client";

import { useId } from "react";

/**
 * SingaporeNetworkMap — Nxeon's Singapore datacenter rendered as the hub of an
 * APAC network: a glowing central node radiating curved routes out to each
 * region, over a dotted/pixel-grid landmass silhouette. Built as pure SVG +
 * CSS (no images, no canvas, no WebGL) so it stays cheap to render and easy
 * to re-theme.
 *
 * Data-driven: add/remove a destination by editing LOCATIONS below — nodes,
 * routes, and labels are all generated from that array.
 *
 * The dotted map itself is NOT drawn as one <circle> per dot (that would be
 * thousands of DOM nodes for a silhouette this size). Instead each landmass
 * is a polygon used only as an SVG clipPath, and the dots come from a tiny
 * tiled <pattern> filled into a couple of clipped <rect>s — a handful of DOM
 * nodes total, however fine the grid looks.
 */

const VIEW_W = 1000;
const VIEW_H = 660;

type LabelSide = "left" | "right" | "top" | "bottom";

interface NetworkLocation {
  id: string;
  name: string;
  flag: string;
  latency: number;
  x: number;
  y: number;
  labelSide: LabelSide;
  /** perpendicular bend of the route curve; sign controls which way it bows */
  bend: number;
}

const SGP = { x: 522, y: 330 };

const LOCATIONS: NetworkLocation[] = [
  { id: "malaysia", name: "Malaysia", flag: "🇲🇾", latency: 18, x: 400, y: 268, labelSide: "left", bend: -0.16 },
  { id: "indonesia", name: "Indonesia", flag: "🇮🇩", latency: 28, x: 452, y: 436, labelSide: "bottom", bend: 0.12 },
  { id: "thailand", name: "Thailand", flag: "🇹🇭", latency: 20, x: 452, y: 150, labelSide: "top", bend: -0.1 },
  { id: "vietnam", name: "Vietnam", flag: "🇻🇳", latency: 22, x: 680, y: 196, labelSide: "right", bend: 0.14 },
  { id: "india", name: "India", flag: "🇮🇳", latency: 38, x: 218, y: 190, labelSide: "left", bend: -0.14 },
  { id: "japan", name: "Japan", flag: "🇯🇵", latency: 52, x: 748, y: 66, labelSide: "right", bend: 0.22 },
  { id: "australia", name: "Australia", flag: "🇦🇺", latency: 48, x: 766, y: 528, labelSide: "right", bend: 0.2 },
];

// Landmass silhouettes — coarse polygons, only ever used as clip paths for the
// dot pattern. Not meant to be coastline-accurate, only recognizable.
const LANDMASSES: string[] = [
  // India / South Asia
  "M118,64 L232,50 L288,84 L300,140 L276,196 L252,252 L222,318 L196,352 L172,306 L150,236 L128,168 L104,110 Z",
  // Mainland SE Asia + South China, tapering into the Malay peninsula toward Singapore
  "M330,10 L560,-10 L700,26 L742,96 L706,150 L640,168 L604,222 L586,278 L560,320 L540,350 L520,372 L500,344 L486,300 L462,262 L440,300 L420,344 L398,306 L376,254 L392,196 L368,150 L346,100 Z",
  // Philippines (decorative island cluster)
  "M736,196 L768,206 L774,244 L752,266 L730,240 Z M770,150 L792,160 L786,190 L762,182 Z",
  // Sumatra
  "M420,360 L470,352 L500,398 L486,452 L452,486 L424,448 L410,404 Z",
  // Java / Borneo / Sulawesi belt trailing toward New Guinea
  "M500,410 L580,398 L648,406 L706,392 L748,404 L738,436 L672,442 L604,440 L536,448 Z M770,392 L820,384 L836,414 L800,428 Z M860,398 L920,394 L934,420 L880,428 Z",
  // Japan archipelago
  "M700,10 L734,4 L762,30 L784,72 L774,112 L748,124 L724,96 L706,60 Z",
  // Australia
  "M632,458 L716,436 L800,442 L866,462 L900,502 L892,552 L846,584 L772,592 L706,576 L654,536 L626,498 Z",
];

function curvePath(a: { x: number; y: number }, b: { x: number; y: number }, bend: number): string {
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2;
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy) || 1;
  // perpendicular unit vector, scaled by bend * length
  const px = (-dy / len) * len * bend;
  const py = (dx / len) * len * bend;
  const cx = mx + px;
  const cy = my + py;
  return `M${a.x},${a.y} Q${cx},${cy} ${b.x},${b.y}`;
}

const LABEL_OFFSET: Record<LabelSide, { dx: number; dy: number; align: "start" | "end" | "center" }> = {
  left: { dx: -14, dy: 0, align: "end" },
  right: { dx: 14, dy: 0, align: "start" },
  top: { dx: 0, dy: -14, align: "center" },
  bottom: { dx: 0, dy: 14, align: "center" },
};

export interface SingaporeNetworkMapProps {
  showLabels?: boolean;
  animated?: boolean;
  className?: string;
}

export function SingaporeNetworkMap({ showLabels = true, animated = true, className }: SingaporeNetworkMapProps) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const ids = {
    dotsDim: `sgmap-dd-${uid}`,
    dotsBright: `sgmap-db-${uid}`,
    land: `sgmap-land-${uid}`,
    bright: `sgmap-bright-${uid}`,
    routeGrad: `sgmap-rg-${uid}`,
    routeFade: `sgmap-rf-${uid}`,
    glow: `sgmap-glow-${uid}`,
    coreGrad: `sgmap-core-${uid}`,
    ringGrad: `sgmap-ring-${uid}`,
    ambient: `sgmap-amb-${uid}`,
    grid: `sgmap-grid-${uid}`,
    nodeGlow: `sgmap-ng-${uid}`,
  };

  const routes = LOCATIONS.map((loc) => ({ loc, d: curvePath(SGP, loc, loc.bend) }));

  return (
    <div className={`sgmap-wrap${className ? ` ${className}` : ""}`} data-animated={animated ? "true" : "false"}>
      <style>{`
        .sgmap-wrap {
          position: relative;
          width: 100%;
          aspect-ratio: ${VIEW_W} / ${VIEW_H};
          background: #050A16;
          border-radius: 20px;
          overflow: hidden;
          container-type: inline-size;
          container-name: sgmap;
          isolation: isolate;
        }
        .sgmap-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
        .sgmap-labels { position: absolute; inset: 0; pointer-events: none; }
        .sgmap-label {
          position: absolute;
          transform: translate(-50%, -50%);
          display: inline-flex;
          align-items: center;
          gap: clamp(4px, 0.9cqw, 8px);
          white-space: nowrap;
          padding: clamp(4px, 0.85cqw, 8px) clamp(6px, 1.1cqw, 12px);
          border-radius: 999px;
          background: rgba(8, 17, 36, 0.72);
          border: 1px solid rgba(59, 130, 246, 0.35);
          backdrop-filter: blur(6px);
          -webkit-backdrop-filter: blur(6px);
          box-shadow: 0 4px 18px rgba(3, 7, 18, 0.45);
        }
        .sgmap-label--sgp {
          border-color: rgba(139, 92, 246, 0.55);
          background: rgba(8, 17, 36, 0.85);
          box-shadow: 0 0 0 1px rgba(59,130,246,0.18), 0 8px 28px rgba(59,130,246,0.22);
          padding: clamp(6px, 1.1cqw, 10px) clamp(10px, 1.6cqw, 16px);
        }
        .sgmap-flag { font-size: clamp(11px, 1.7cqw, 16px); line-height: 1; }
        .sgmap-name {
          font-size: clamp(9.5px, 1.5cqw, 13px);
          font-weight: 500;
          color: #F8FAFC;
          font-family: var(--font-geist-sans, ui-sans-serif, system-ui, sans-serif);
        }
        .sgmap-label--sgp .sgmap-name { font-size: clamp(11px, 1.9cqw, 15px); font-weight: 600; }
        .sgmap-latency {
          font-size: clamp(8.5px, 1.3cqw, 11.5px);
          font-weight: 600;
          color: #3B82F6;
          background: rgba(22, 119, 255, 0.12);
          padding: clamp(1px, 0.35cqw, 3px) clamp(4px, 0.8cqw, 7px);
          border-radius: 999px;
          font-family: var(--font-geist-mono, ui-monospace, monospace);
        }
        .sgmap-particle { filter: url(#${ids.glow}); }
        @keyframes sgmap-travel { 0% { offset-distance: 0%; opacity: 0; } 8% { opacity: 1; } 90% { opacity: 1; } 100% { offset-distance: 100%; opacity: 0; } }
        @keyframes sgmap-pulse-node { 0%, 100% { transform: scale(1); opacity: 0.9; } 50% { transform: scale(1.35); opacity: 1; } }
        @keyframes sgmap-pulse-sgp { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.08); } }
        @keyframes sgmap-ring { 0%, 100% { opacity: 0.55; transform: scale(1); } 50% { opacity: 0.95; transform: scale(1.045); } }
        .sgmap-wrap[data-animated="true"] .sgmap-particle { animation: sgmap-travel linear infinite; }
        .sgmap-wrap[data-animated="true"] .sgmap-endpoint-dot { animation: sgmap-pulse-node ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
        .sgmap-wrap[data-animated="true"] .sgmap-sgp-core { animation: sgmap-pulse-sgp 2.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
        .sgmap-wrap[data-animated="true"] .sgmap-ring { animation: sgmap-ring ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
        @media (prefers-reduced-motion: reduce) {
          .sgmap-wrap[data-animated="true"] .sgmap-particle { animation: none !important; opacity: 0 !important; }
          .sgmap-wrap[data-animated="true"] .sgmap-endpoint-dot,
          .sgmap-wrap[data-animated="true"] .sgmap-sgp-core,
          .sgmap-wrap[data-animated="true"] .sgmap-ring { animation: none !important; }
        }
