          .sgmap-latency { display: none; }
        }
      `}</style>

      <svg className="sgmap-svg" viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} role="img" aria-label="Nxeon Singapore datacenter network map, connecting to Malaysia, Indonesia, Thailand, Vietnam, India, Japan, and Australia">
        <defs>
          <pattern id={ids.dotsDim} width="9" height="9" patternUnits="userSpaceOnUse">
            <circle cx="2" cy="2" r="0.85" fill="#1677FF" fillOpacity="0.4" />
          </pattern>
          <pattern id={ids.dotsBright} width="9" height="9" patternUnits="userSpaceOnUse">
            <circle cx="2" cy="2" r="1.05" fill="#8FB8FF" fillOpacity="0.9" />
          </pattern>
          <clipPath id={ids.land}>
            {LANDMASSES.map((d, i) => (
              <path key={i} d={d} />
            ))}
          </clipPath>
          <mask id={ids.bright}>
            <rect width={VIEW_W} height={VIEW_H} fill="#000" />
            <radialGradient id={`${ids.bright}-sgp`} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform={`translate(${SGP.x} ${SGP.y}) scale(300)`}>
              <stop offset="0%" stopColor="#fff" stopOpacity="1" />
              <stop offset="100%" stopColor="#fff" stopOpacity="0" />
            </radialGradient>
            <rect width={VIEW_W} height={VIEW_H} fill={`url(#${ids.bright}-sgp)`} />
            {LOCATIONS.map((loc) => (
              <circle key={loc.id} cx={loc.x} cy={loc.y} r="85" fill="#fff" opacity="0.55" style={{ filter: "blur(20px)" }} />
            ))}
          </mask>
          <linearGradient id={ids.routeGrad} gradientUnits="userSpaceOnUse" x1="140" y1="0" x2="880" y2="0">
            <stop offset="0%" stopColor="#1677FF" />
            <stop offset="45%" stopColor="#3B82F6" />
            <stop offset="100%" stopColor="#8B5CF6" />
          </linearGradient>
          <radialGradient id={ids.routeFade} cx="0" cy="0" r="1" gradientUnits="userSpaceOnUse" gradientTransform={`translate(${SGP.x} ${SGP.y}) scale(620)`}>
            <stop offset="0%" stopColor="#fff" stopOpacity="1" />
            <stop offset="100%" stopColor="#9fb3d9" stopOpacity="0.45" />
          </radialGradient>
          <mask id={ids.routeFade + "-mask"}>
            <rect width={VIEW_W} height={VIEW_H} fill={`url(#${ids.routeFade})`} />
          </mask>
          <filter id={ids.glow} x="-200%" y="-200%" width="500%" height="500%">
            <feGaussianBlur stdDeviation="1.6" />
          </filter>
          <filter id={ids.nodeGlow} x="-300%" y="-300%" width="700%" height="700%">
            <feGaussianBlur stdDeviation="9" />
          </filter>
          <radialGradient id={ids.coreGrad} cx="35%" cy="30%" r="75%">
            <stop offset="0%" stopColor="#F8FAFC" />
            <stop offset="45%" stopColor="#BFDBFE" />
            <stop offset="100%" stopColor="#1677FF" />
          </radialGradient>
          <radialGradient id={ids.ambient} cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#1677FF" stopOpacity="0.22" />
            <stop offset="55%" stopColor="#7C3AED" stopOpacity="0.1" />
            <stop offset="100%" stopColor="#050A16" stopOpacity="0" />
          </radialGradient>
          <pattern id={ids.grid} width="66" height="66" patternUnits="userSpaceOnUse">
            <path d="M66,0 L0,0 0,66" fill="none" stroke="#1677FF" strokeOpacity="0.07" strokeWidth="1" />
          </pattern>
        </defs>

        {/* base */}
        <rect width={VIEW_W} height={VIEW_H} fill="#050A16" />
        <rect width={VIEW_W} height={VIEW_H} fill={`url(#${ids.grid})`} opacity="0.6" />
        <ellipse cx={SGP.x} cy={SGP.y} rx="480" ry="360" fill={`url(#${ids.ambient})`} />

        {/* dotted landmass */}
        <rect width={VIEW_W} height={VIEW_H} fill={`url(#${ids.dotsDim})`} clipPath={`url(#${ids.land})`} />
        <rect width={VIEW_W} height={VIEW_H} fill={`url(#${ids.dotsBright})`} clipPath={`url(#${ids.land})`} mask={`url(#${ids.bright})`} />

        {/* routes + traveling particles */}
        <g mask={`url(#${ids.routeFade}-mask)`}>
          {routes.map(({ loc, d }, i) => (
            <g key={loc.id}>
              <path d={d} fill="none" stroke={`url(#${ids.routeGrad})`} strokeWidth={loc.id === "australia" || loc.id === "japan" ? 1.6 : 1.3} strokeLinecap="round" opacity="0.78" />
              {[0, 1].map((p) => (
                <circle
                  key={p}
                  className="sgmap-particle"
                  r={p === 0 ? 2.6 : 2}
                  fill="#EAF2FF"
                  style={{
                    offsetPath: `path('${d}')`,
                    offsetRotate: "0deg",
                    animationDuration: `${3.4 + i * 0.35 + p * 1.1}s`,
                    animationDelay: `${-(i * 0.6 + p * 1.8)}s`,
                  }}
                />
              ))}
            </g>
          ))}
        </g>

        {/* destination nodes */}
        {LOCATIONS.map((loc, i) => (
          <g key={loc.id}>
            <circle cx={loc.x} cy={loc.y} r="13" fill="#3B82F6" opacity="0.16" filter={`url(#${ids.nodeGlow})`} />
            <circle className="sgmap-endpoint-dot" cx={loc.x} cy={loc.y} r="3.6" fill="#EAF2FF" style={{ animationDuration: `${3.2 + (i % 4) * 0.5}s`, animationDelay: `${-(i * 0.7)}s` }} />
          </g>
        ))}

        {/* Singapore hub */}
        <g>
          <circle cx={SGP.x} cy={SGP.y} r="95" fill="#1677FF" opacity="0.14" filter={`url(#${ids.nodeGlow})`} />
          <circle cx={SGP.x} cy={SGP.y} r="60" fill="#7C3AED" opacity="0.14" filter={`url(#${ids.nodeGlow})`} />
          <circle className="sgmap-ring" cx={SGP.x} cy={SGP.y} r="34" fill="none" stroke="#8B5CF6" strokeWidth="1.4" opacity="0.6" style={{ animationDuration: "3.4s" }} />
          <circle className="sgmap-ring" cx={SGP.x} cy={SGP.y} r="23" fill="none" stroke="#3B82F6" strokeWidth="1.6" opacity="0.75" style={{ animationDuration: "2.6s", animationDelay: "-0.6s" }} />
          <circle className="sgmap-sgp-core" cx={SGP.x} cy={SGP.y} r="10" fill={`url(#${ids.coreGrad})`} />
        </g>
      </svg>

      {showLabels && (
        <div className="sgmap-labels">
          {LOCATIONS.map((loc) => {
            const off = LABEL_OFFSET[loc.labelSide];
            const leftPct = ((loc.x + off.dx) / VIEW_W) * 100;
            const topPct = ((loc.y + off.dy) / VIEW_H) * 100;
            const translate =
              off.align === "end" ? "translate(-100%, -50%)" : off.align === "start" ? "translate(0%, -50%)" : off.dy < 0 ? "translate(-50%, -100%)" : "translate(-50%, 0%)";
            return (
              <div key={loc.id} className="sgmap-label" style={{ left: `${leftPct}%`, top: `${topPct}%`, transform: translate }}>
                <span className="sgmap-flag">{loc.flag}</span>
                <span className="sgmap-name">{loc.name}</span>
                <span className="sgmap-latency">{loc.latency}ms</span>
              </div>
            );
          })}
          <div
            className="sgmap-label sgmap-label--sgp"
            style={{ left: `${((SGP.x + 34) / VIEW_W) * 100}%`, top: `${(SGP.y / VIEW_H) * 100}%`, transform: "translate(0%, -50%)" }}
          >
            <span className="sgmap-flag">🇸🇬</span>
            <span className="sgmap-name">Singapore</span>
          </div>
        </div>
      )}
    </div>
  );
}

